				if (/row-level security|policy|not allowed|403/i.test(msg)) throw new Error("Нет прав на загрузку (нужен вход) или в Supabase не применён secure_storage_upload.sql");
				if (/bucket|not found/i.test(msg)) throw new Error("Хранилище ещё не настроено: в Supabase запусти SQL admin_files_codes.sql");
				throw new Error(msg);
