	async function listStarostaCodes() {
		const session = getSession();
		if (!session || session.role !== "admin") throw new Error("Только админ");
		if (supabaseConfigured) {
			if (!session.token) throw new Error("Нет связи с общей базой — обнови страницу и войди снова");
			const { data, error } = await supabase.rpc("rasp_list_starosta_codes", { p_token: session.token });
			if (error) throw new Error(rpcErrorMessage(error));
			let rows = data;
			if (typeof rows === "string") try {
				rows = JSON.parse(rows);
			} catch {
				rows = [];
			}
			if (!Array.isArray(rows)) return [];
			return rows.map((r) => {
				const allGroups = r.allGroups === true || r.allgroups === true || r.all_groups === true || r.groupId === "__all__";
				return {
					id: r.id,
					groupId: allGroups ? ALL_GROUPS_ID : r.groupId || r.group_id,
					groupName: allGroups ? "Все группы" : r.groupName || r.group_name || "",
					allGroups,
					label: r.label || "",
					roleTitle: r.roleTitle || r.roletitle || r.role_title || "",
					code: r.code || r.code_plain || "",
					createdAt: r.createdAt || r.created_at || "",
					active: r.active !== false,
					canFreeRooms: r.canFreeRooms === true || r.canfreerooms === true || r.can_free_rooms === true,
					banned: r.banned === true,
					banReason: r.banReason || r.banreason || r.ban_reason || ""
				};
			});
		}
		const out = [];
		for (const c of db.globalStarostaCodes || []) {
			if (c.active === false) continue;
			out.push({
				id: c.id,
				groupId: ALL_GROUPS_ID,
				groupName: "Все группы",
				allGroups: true,
				label: c.label || "",
				roleTitle: c.roleTitle || "",
				code: c.code || "",
				createdAt: c.createdAt,
				active: true,
				canFreeRooms: !!c.canFreeRooms,
				banned: !!c.banned,
				banReason: c.banReason || ""
			});
		}
		for (const g of db.groups) for (const c of g.starostaCodes || []) {
			if (c.active === false) continue;
			out.push({
				id: c.id,
				groupId: g.id,
				groupName: g.name,
				allGroups: false,
				label: c.label || "",
				roleTitle: c.roleTitle || "",
				code: c.code || "",
				createdAt: c.createdAt,
				active: true,
				canFreeRooms: !!c.canFreeRooms,
				banned: !!c.banned,
				banReason: c.banReason || ""
			});
		}
		return out;
	}
