		let bestCount = 0;
		const maxScan = Math.min(rows.length, 40);
		for (let r = 0; r < maxScan; r++) {
			const line = rows[r] || [];
			let count = 0;
			for (const cell of line) if (/группа/i.test(String(cell || ""))) count++;
			if (count > bestCount) {
				bestCount = count;
				groupRow = r;
			}
		}
		if (groupRow < 0 || bestCount < 2) throw new Error("Не узнал шаблон: в файле нет строки с названиями групп («Группа 0901-ПД1»). Проверь, что это расписание колледжа.");
